package pe.com.dentalamericana.finance.dto;import jakarta.validation.constraints.*;import pe.com.dentalamericana.finance.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
public final class FinanceDtos{private FinanceDtos(){}public record MethodResponse(Long id,String code,String name,boolean referenceRequired){public static MethodResponse from(PaymentMethod m){return new MethodResponse(m.getId(),m.getCode(),m.getName(),m.isReferenceRequired());}}public record OpenCashRequest(@NotNull@DecimalMin("0.00")BigDecimal openingAmount){}public record CloseCashRequest(@NotNull@DecimalMin("0.00")BigDecimal countedAmount,@Size(max=1000)String observation,@NotNull Long version,@AssertTrue boolean confirmation){}public record CashSessionResponse(Long id,Long openedBy,Instant openedAt,BigDecimal openingAmount,CashSessionStatus status,Long closedBy,Instant closedAt,BigDecimal expectedAmount,BigDecimal countedAmount,BigDecimal difference,String closingObservation,Long version){}public record AccountResponse(Long id,Long planId,Long patientId,String patientName,String planCode,BigDecimal totalAmount,BigDecimal paidAmount,BigDecimal balance,ReceivableStatus status,LocalDate dueDate,Instant updatedAt,Long version){}public record PaymentRequest(@NotNull Long accountId,@NotNull Long paymentMethodId,@NotNull@DecimalMin("0.01")BigDecimal amount,@Size(max=120)String reference,@AssertTrue boolean confirmation){}public record PaymentResponse(Long id,Long accountId,Long patientId,String patientName,Long planId,String planCode,Long cashSessionId,Long paymentMethodId,String paymentMethod,BigDecimal amount,String reference,String receiptNumber,FinancialRecordStatus status,Instant registeredAt){}public record ExpenseRequest(@NotBlank@Size(max=80)String category,@NotBlank@Size(max=500)String description,@Size(max=150)String provider,@Size(max=80)String documentReference,@NotNull Long paymentMethodId,@NotNull@DecimalMin("0.01")BigDecimal amount,@AssertTrue boolean confirmation){}public record ExpenseResponse(Long id,Long cashSessionId,String category,String description,String provider,String documentReference,Long paymentMethodId,String paymentMethod,BigDecimal amount,FinancialRecordStatus status,Instant registeredAt){}public record MovementResponse(Long id,Long cashSessionId,MovementType type,String category,String source,Long sourceId,String paymentMethod,BigDecimal amount,String description,Instant createdAt){}public record FinanceDashboard(BigDecimal income,BigDecimal expenses,BigDecimal net,BigDecimal receivable,BigDecimal cashIncome,BigDecimal digitalIncome,int paymentsCount,int expensesCount,List<MovementResponse>recentMovements){}
}
